if os.path.exists('/proc'):
    print("/proc directory exists")
    try:
        entries = os.listdir('/proc')
        print(f"Found {len(entries)} entries in /proc")
        # Show first 10 entries
        print("First 10 entries:", entries[:10])
    except PermissionError:
        print("Permission denied accessing /proc")
    except Exception as e:
        print(f"Error accessing /proc: {e}")
else:
